import os, pypdf

for root, dirs, files in os.walk('/filesystem'):
    for f in files:
        if f.endswith('.pdf'):
            p = os.path.join(root, f)
            try:
                r = pypdf.PdfReader(p)
                for i, page in enumerate(r.pages):
                    t = page.extract_text()
                    if 'plant-room' in t.lower() or 'plant room' in t.lower():
                        print(f'{f} p.{i+1}: matches plant room')
            except Exception as e:
                pass
